  "sozluk": {
    "sozluk_surumu": 1,
    "girdiler": [
      {
        "id": "hr042_peribacasi",
        "tur": "kelime",
        "yazim": "peribacaları",
        "anlam": "Rüzgâr ve suyun yumuşak kayaçları aşındırmasıyla oluşan sivri kaya kuleleri.",
        "sinif_alt": 4,
        "sinif_ust": 6
      },
      {
        "id": "hr042_tepe",
        "tur": "kelime",
        "yazim": "tepe",
        "anlam": "Çevresine göre yükselen kara parçası.",
        "sinif_alt": 4,
        "sinif_ust": 6
      },
      {
        "id": "hr042_vadi",
        "tur": "kelime",
        "yazim": "vadi",
        "anlam": "İki yamaç arasında kalan, genellikle akarsuyun açtığı çukur.",
        "sinif_alt": 4,
        "sinif_ust": 6
      },
      {
