-- Sözlük: tahmini → tahminî (yalnız eski değer eşleşirse)
do $z$
declare v_n integer;
begin
  update public.okuma_sozluk_girdileri
     set anlam = 'Ölçmeden, tahminî olarak.'
   where id = 'hr074_goz_karari' and anlam = 'Ölçmeden, tahmini olarak.';
  get diagnostics v_n = row_count;
  raise notice 'sozluk hr074_goz_karari güncellenen satır: %', v_n;
end $z$;
